<?php
declare(strict_types=1);
require_once __DIR__.'/Support/ReviewedLocalFixture.php';
use DigiForge\Portal\ReviewedAcceptanceContract as Contract;
final class AcceptanceContractStatusTest extends WP_UnitTestCase {
 private array $actors;
 private string $criterion='BP-portal-17-conversion';
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();$this->actors=ReviewedLocalFixture::actors('digital');(new DigiForge\REST\ReviewedContractsController())->register();(new DigiForge\Security\ShopAccessRestGuard())->register();do_action('rest_api_init');}
 private function input():array{return ['version'=>1,'criterion'=>$this->criterion,'scope'=>'fixture-v1','workflow'=>'research','definition'=>['numerator'=>'Synthetic reviewed events','denominator'=>'Synthetic reviewed population','population'=>'Synthetic only','attribution'=>'Stored shop/workflow identities','period_start'=>'2026-01-01T00:00:00Z','period_end'=>'2026-02-01T00:00:00Z','source_records'=>[['shop_key'=>'digital','reference'=>'local://synthetic/evidence','sha256'=>hash('sha256','synthetic')]],'formula_ref'=>null]];}
 private function propose(int $effective=0):array {$p=Contract::propose('digital',$this->input(),$effective?:time()-1,time()+3600,wp_generate_uuid4(),0);self::assertNotWPError($p);return $p;}
 private function decide(array $p,string $decision='APPROVED'):array {wp_set_current_user($this->actors['reviewer']);$r=Contract::decide('digital',$this->criterion,'fixture-v1',$p['revision'],$p['proposal_hash'],$decision,wp_generate_uuid4());self::assertNotWPError($r);wp_set_current_user($this->actors['author']);return $r;}
 private function read(string $shop='digital',array $query=[],string $method='GET'):WP_REST_Response {$r=new WP_REST_Request($method,'/digiforge/v1/reviewed-contracts/'.$shop.'/acceptance');$r->set_query_params($query?:['criterion'=>$this->criterion,'scope'=>'fixture-v1']);return rest_get_server()->dispatch($r);}
 public function testRealGetDispatchIsScopedReadOnlyAndNeverCertifies():void {
  $this->decide($this->propose());$before=$this->snapshot();$r=$this->read();self::assertSame(200,$r->get_status());$s=$r->get_data();self::assertSame($this->criterion,$s['criterion']);self::assertSame('fixture-v1',$s['scope']);self::assertSame('APPROVED',$s['review_status']);self::assertSame('CURRENT_REVIEW',$s['status']);self::assertSame('UNKNOWN',$s['value_state']);self::assertSame('UNVERIFIED',$s['evidence_state']);self::assertSame('local://synthetic/evidence',$s['evidence_references'][0]['reference']);self::assertIsInt($s['expires_at']);self::assertFalse($s['revoked']);self::assertFalse($s['external_execution_authorized']);self::assertArrayNotHasKey('payload',$s);self::assertSame($before,$this->snapshot());self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }
 private function snapshot():array {global $wpdb;return [$wpdb->get_results("SELECT * FROM {$wpdb->options} WHERE option_name LIKE 'digiforge_local_review_%'",ARRAY_A),$wpdb->get_results('SELECT * FROM '.DigiForge\Database\Tables::audit_log()." WHERE object_type='reviewed_local_evidence' ORDER BY id",ARRAY_A)];}
 public function testAnonymousForeignDeferredWritesAndMalformedQueriesDeny():void {
  self::assertSame(403,$this->read('personalized_pod')->get_status());foreach(['standard_pod','jewelry']as $shop)self::assertSame(403,$this->read($shop)->get_status());self::assertNotSame(200,$this->read('digital',[],'POST')->get_status());self::assertNotSame(200,$this->read('digital',[],'DELETE')->get_status());foreach([['criterion'=>$this->criterion,'scope'=>'fixture-v1','shop'=>'jewelry'],['criterion'=>[$this->criterion],'scope'=>'fixture-v1'],['criterion'=>$this->criterion,'scope'=>'../private']]as $q)self::assertGreaterThanOrEqual(400,$this->read('digital',$q)->get_status());wp_set_current_user(0);self::assertSame(401,$this->read()->get_status());
 }
 public function testMissingPendingRevokedAndFutureStatesStayUnknown():void {
  self::assertSame('MISSING',$this->read()->get_data()['status']);$p=$this->propose();self::assertSame('PENDING',$this->read()->get_data()['status']);$a=$this->decide($p);$this->decide($a,'REVOKED');$r=$this->read()->get_data();self::assertSame('REVOKED',$r['status']);self::assertTrue($r['revoked']);self::assertSame('UNKNOWN',$r['value_state']);
 }
 public function testFutureReviewAndRevokedAssignmentCannotBeCurrent():void {$this->decide($this->propose(time()+600));self::assertSame('NOT_EFFECTIVE',$this->read()->get_data()['status']);ShopAccessFixture::provision([]);self::assertSame(403,$this->read()->get_status());}
 public function testMalformedSignedPayloadDoesNotExposeReferences():void {$key='acceptance:v1:'.$this->criterion.':fixture-v1';self::assertNotWPError(DigiForge\Security\ReviewedLocalEvidence::propose('policy','digital',$key,['version'=>999,'reference'=>'https://unsafe.invalid/<script>'],time()-1,time()+300,wp_generate_uuid4(),0));$data=$this->read()->get_data();self::assertSame('INVALID_EVIDENCE',$data['status']);self::assertSame([],$data['evidence_references']);self::assertStringNotContainsString('unsafe.invalid',wp_json_encode($data));}
 public function testReviewerAuthorityLossInvalidatesCurrentReview():void {$this->decide($this->propose());(new WP_User($this->actors['reviewer']))->set_role('subscriber');self::assertSame('REVIEW_STALE',$this->read()->get_data()['status']);}
 public function testExpiredReviewIsDisplayedWithoutAuthority():void {$p=Contract::propose('digital',$this->input(),time()-1,time()+2,wp_generate_uuid4(),0);self::assertNotWPError($p);$this->decide($p);while(time()<$p['expires_at'])usleep(50000);$data=$this->read()->get_data();self::assertSame('EXPIRED',$data['status']);self::assertFalse($data['external_execution_authorized']);}
 public function testPlainPermalinkMetadataAndBodyRejection():void {self::assertSame(200,$this->read('digital',['criterion'=>$this->criterion,'scope'=>'fixture-v1','rest_route'=>'/digiforge/v1/reviewed-contracts/digital/acceptance'])->get_status());$r=new WP_REST_Request('GET','/digiforge/v1/reviewed-contracts/digital/acceptance');$r->set_query_params(['criterion'=>$this->criterion,'scope'=>'fixture-v1']);$r->set_body('{"shop":"personalized_pod"}');self::assertSame(400,rest_get_server()->dispatch($r)->get_status());}
 public function testDatabaseFailureIsUnavailableNotMissing():void {
  global $wpdb;$this->decide($this->propose());$table=DigiForge\Database\Tables::audit_log();$fault=static function(string $sql)use($table):string{return str_contains($sql,$table)&&str_starts_with(ltrim($sql),'SELECT')?'SELECT * FROM digiforge_synthetic_absent_audit_table':$sql;};
  $previous=$wpdb->suppress_errors(true);add_filter('query',$fault);
  try{$response=$this->read();self::assertGreaterThanOrEqual(400,$response->get_status());self::assertArrayNotHasKey('evidence_references',$response->get_data());}finally{remove_filter('query',$fault);$wpdb->suppress_errors($previous);}
 }
 public function testExplicitReadOnlyShopAssignmentCanInspectWithoutWriteAuthority():void {$id=self::factory()->user->create(['role'=>'administrator']);ShopAccessFixture::authorizeActor($id,['digital'],['manage_digiforge']);wp_set_current_user($id);self::assertSame(200,$this->read()->get_status());self::assertSame(403,$this->read('personalized_pod')->get_status());self::assertFalse(DigiForge\Security\ShopAccess::authorize('digital','manage_digiforge_settings')===true);}
 public function testNativePortalHasOnlyReadControlsAndSafeStatusRegion():void {ob_start();DigiForge\Portal\ReviewedContractsPanel::render('digital');$html=(string)ob_get_clean();self::assertStringContainsString('data-acceptance-status',$html);$doc=new DOMDocument();@$doc->loadHTML('<?xml encoding="UTF-8">'.$html);$x=new DOMXPath($doc);$root=$x->query('//*[@data-acceptance-status]')->item(0);self::assertNotNull($root);self::assertSame(0,$x->query('.//*[@data-contract-decisions]|.//*[@name="decision"]|.//*[@name="token"]',$root)->length);self::assertSame(1,$x->query('.//*[@role="status"][@aria-live="polite"]',$root)->length);$dir=getenv('DF_ACCEPTANCE_STATUS_FIXTURE_DIR');if($dir)file_put_contents($dir.'/acceptance-status.html',$html);}
}
